        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // 10% of 1000 = 100, remaining 900; 10% of 900 = 90 → total 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("order matters in chain mode", () => {
      // Fixed 200 first, then 10% of remaining
      const compositeA = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(200), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // Fixed 200 off 1000 → remaining 800; 10% of 800 = 80 → total 280
      expect(compositeA.computeDiscountCents(1000)).toBe(280);

      // 10% first, then fixed 200
      const compositeB = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // 10% of 1000 = 100 → remaining 900; fixed 200 off 900 → total 300
      expect(compositeB.computeDiscountCents(1000)).toBe(300);
    });

    it("stops reducing when remaining reaches zero", () => {
